tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD:$PWD/scripts/ringer/stage7:$PWD/scripts/ringer/phase1 TMPDIR=/tmp
PY=.venv/bin/python
grep -n "turn_index = 2" scripts/ringer/phase2/act3c_probe.py && { echo "WHY: turn_index hack remains"; exit 1; }
sed -n '/^def run(/,/^def main/p' scripts/ringer/phase2/act3c_probe.py | grep -n "BROADCAST_COMMAND, ARCHIVE_COMMAND, \*NEUTRAL" && { echo "WHY: live stall still scripts the episodes"; exit 1; }
$PY -m ruff format --check scripts/ringer/phase2 tests/test_act3c_probe.py || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check scripts/ringer/phase2 tests/test_act3c_probe.py || { echo "WHY: ruff check failed"; exit 1; }
for p in none clean costly stall; do O=$(mktemp -d); $PY scripts/ringer/phase2/act3c_probe.py --prefix $p --n 1 --out $O --dry-run || { echo "WHY: dry run failed for $p"; exit 1; }; $PY scripts/ringer/phase2/check_act3c_probe.py $O 1 --mode dry || { echo "WHY: probe check failed for $p"; exit 1; }; done
O=$(mktemp -d); $PY scripts/ringer/phase2/act3c_probe.py --prefix stall --n 1 --out $O --dry-run; $PY - $O <<'EOF2'
import json,sys
r=json.load(open(sys.argv[1]+'/results.json'))['rows'][0]
assert r['exit_cause']=='neutral_recovery' and r['story_complete'], r
assert r['window_event_fired_turn']==9 and r['nudge_event_fired_turn']==10, (r['window_event_fired_turn'], r['nudge_event_fired_turn'])
assert 'archive_copies_distributed' not in r['final_true_facts'], 'stall must not finish the archive episode'
print('stall dry ok', r['window_event_fired_turn'], r['nudge_event_fired_turn'])
EOF2
[ $? -eq 0 ] || { echo "WHY: honest dry stall assertions failed"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_act3c_probe.py || { echo "WHY: probe tests failed"; exit 1; }
echo ok
